package ec.edu.uagraria.prog3; import ec.edu.uagraria.prog3.dominio.Arroz;import ec.edu.uagraria.prog3.fabrica.DatosProducto;import ec.edu.uagraria.prog3.fabrica.FabricaProductos;import ec.edu.uagraria.prog3.fabrica.TipoProducto;import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*; class ArrozTest {     private static Arroz arroz(int ciclos) {        return (Arroz) FabricaProductos.crear(                TipoProducto.ARROZ, DatosProducto.deArroz(ciclos));    }     @Test    void debeGuardarLosCiclosPorAnio() {        Arroz arroz = arroz(2);         assertEquals(2, arroz.ciclosPorAnio());    }     @Test    void debeDevolverElNombreComun() {        Arroz arroz = arroz(2);         assertEquals("Arroz (2 ciclos/año)", arroz.nombreComun());    } }